// ============================================================
// aes_uart_top.v  (rewritten)
//
// UART <-> AES-128 core wrapper
//
//   PC -> FPGA : A5, 16B plaintext (MSB first), 16B key (MSB first)
//   FPGA -> PC : 5A, 16B ciphertext (MSB first)
//
// Fixes vs. previous version:
//   1. aes_start is generated by an RX state that advances on every
//      clock (not gated by rx_valid), so AES actually starts.
//   2. TX FSM waits for tx_busy to RISE after pulsing tx_start, then
//      waits for it to FALL before the next byte (no dropped bytes).
//   3. RX and TX FSMs are separate always blocks, each owning its regs.
// ============================================================
module aes_uart_top #(
    parameter integer CLK_FREQ  = 100_000_000,
    parameter integer BAUD_RATE = 115200
)(
    input  wire clk,
    input  wire rst,        // active-high (Arty BTN0)
    input  wire uart_rx,
    output wire uart_tx
);

    // ---------------- UART RX ----------------
    wire [7:0] rx_data;
    wire       rx_valid;

    uart_rx #(.CLK_FREQ(CLK_FREQ), .BAUD_RATE(BAUD_RATE)) u_uart_rx (
        .clk(clk), .rst(rst), .rx(uart_rx),
        .data(rx_data), .data_valid(rx_valid)
    );

    // ---------------- UART TX ----------------
    reg  [7:0] tx_data;
    reg        tx_start;
    wire       tx_busy;

    uart_tx #(.CLK_FREQ(CLK_FREQ), .BAUD_RATE(BAUD_RATE)) u_uart_tx (
        .clk(clk), .rst(rst),
        .data(tx_data), .start(tx_start),
        .tx(uart_tx), .busy(tx_busy)
    );

    // ---------------- AES ----------------
    reg  [127:0] aes_plaintext;
    reg  [127:0] aes_key;
    reg          aes_start;
    wire [127:0] aes_ciphertext;
    wire         aes_done;
    wire         phase_ce;

    aes_top u_aes (
        .clk(clk), .rst(rst), .start(aes_start),
        .plaintext(aes_plaintext), .key(aes_key),
        .ciphertext(aes_ciphertext), .done(aes_done),
        .phase_ce(phase_ce)
    );

    // ========================================================
    // RX FSM : A5 | 16B plaintext | 16B key | pulse aes_start
    // ========================================================
    localparam [1:0] RX_WAIT_HEADER = 2'd0,
                     RX_PLAINTEXT   = 2'd1,
                     RX_KEY         = 2'd2,
                     RX_START_AES   = 2'd3;

    reg [1:0] rx_state;
    reg [3:0] rx_count;     // 0..15

    always @(posedge clk) begin
        if (rst) begin
            rx_state      <= RX_WAIT_HEADER;
            rx_count      <= 4'd0;
            aes_plaintext <= 128'd0;
            aes_key       <= 128'd0;
            aes_start     <= 1'b0;
        end else begin
            aes_start <= 1'b0;                  // default: one-cycle pulse

            if (rx_state == RX_START_AES) begin
                // Runs on the clock AFTER the last key byte landed, so
                // aes_key is fully registered. NOT gated by rx_valid.
                aes_start <= 1'b1;
                rx_state  <= RX_WAIT_HEADER;
            end
            else if (rx_valid) begin
                case (rx_state)
                    RX_WAIT_HEADER: begin
                        if (rx_data == 8'hA5) begin
                            rx_state <= RX_PLAINTEXT;
                            rx_count <= 4'd0;
                        end
                    end

                    RX_PLAINTEXT: begin
                        aes_plaintext <= {aes_plaintext[119:0], rx_data};
                        if (rx_count == 4'd15) begin
                            rx_state <= RX_KEY;
                            rx_count <= 4'd0;
                        end else
                            rx_count <= rx_count + 1'b1;
                    end

                    RX_KEY: begin
                        aes_key <= {aes_key[119:0], rx_data};
                        if (rx_count == 4'd15) begin
                            rx_state <= RX_START_AES;
                            rx_count <= 4'd0;
                        end else
                            rx_count <= rx_count + 1'b1;
                    end

                    default: rx_state <= RX_WAIT_HEADER;
                endcase
            end
        end
    end

    // ========================================================
    // TX FSM : 5A | 16B ciphertext
    //
    // tx_start at cycle t -> uart_tx sees it at t+1 -> tx_busy is high
    // from t+2. So after pulsing start we must WAIT for busy to rise
    // before looking at !tx_busy again.
    // ========================================================
    localparam [1:0] TX_IDLE      = 2'd0,
                     TX_SEND      = 2'd1,   // issue one byte when UART free
                     TX_WAIT_BUSY = 2'd2,   // wait for busy to go high
                     TX_WAIT_DONE = 2'd3;   // wait for busy to go low

    reg [1:0]   tx_state;
    reg [4:0]   tx_count;       // 0 = header, 1..16 = ciphertext bytes
    reg [127:0] tx_ct;

    always @(posedge clk) begin
        if (rst) begin
            tx_state <= TX_IDLE;
            tx_count <= 5'd0;
            tx_ct    <= 128'd0;
            tx_data  <= 8'h00;
            tx_start <= 1'b0;
        end else begin
            tx_start <= 1'b0;                   // default: one-cycle pulse

            case (tx_state)
                TX_IDLE: begin
                    if (aes_done) begin
                        tx_ct    <= aes_ciphertext;
                        tx_count <= 5'd0;
                        tx_state <= TX_SEND;
                    end
                end

                TX_SEND: begin
                    if (!tx_busy) begin
                        if (tx_count == 5'd0)
                            tx_data <= 8'h5A;
                        else begin
                            tx_data <= tx_ct[127:120];      // MSB first
                            tx_ct   <= {tx_ct[119:0], 8'h00};
                        end
                        tx_start <= 1'b1;
                        tx_state <= TX_WAIT_BUSY;
                    end
                end

                TX_WAIT_BUSY: begin
                    if (tx_busy) tx_state <= TX_WAIT_DONE;
                end

                TX_WAIT_DONE: begin
                    if (!tx_busy) begin
                        if (tx_count == 5'd16)
                            tx_state <= TX_IDLE;
                        else begin
                            tx_count <= tx_count + 1'b1;
                            tx_state <= TX_SEND;
                        end
                    end
                end
            endcase
        end
    end

endmodule